    function getShapesFromDesc($shapesDesc) {
        $shapes = json_decode($shapesDesc, true);
        return array_map(
            fn(array $shapeData) => TiocShape::fromArray($shapeData),
            $shapes
        );
    }

    function getAllRoomsExcept($exceptedRoom) {
        $rooms = [
            BOAT_ROOMS_ID_PARROT_BACK,
            BOAT_ROOMS_ID_MOON_TOP,
            BOAT_ROOMS_ID_MOON_BOTTOM,
            BOAT_ROOMS_ID_APPLE_MIDDLE,
            BOAT_ROOMS_ID_CORN_FRONT,
            BOAT_ROOMS_ID_PARROT_FRONT,
            BOAT_ROOMS_ID_PARROT_FRONT + 1
        ];
        unset($rooms[$exceptedRoom]);

        return array_values($rooms);
    }

