        $this->testOBoatGetPlayerUnfilledRoomIdsWithAppleMiddle();
        $this->testOBoatGetPlayerUnfilledRoomIdsWithCornFront();
        $this->testOBoatGetPlayerUnfilledRoomIdsWithParrotFront();
        $this->testOBoatGetPlayerUnfilledRoomIdsWithCentralZone();
